apiVersion: apps/v1
kind: Deployment
metadata:
  name: paperless
  annotations:
    reloader.stakater.com/auto: "true"
spec:
  replicas: 1
  selector:
    matchLabels: {app: paperless}
  template:
    metadata:
      labels: {app: paperless}
    spec:
      securityContext: {runAsUser: 1000, runAsGroup: 1000, fsGroup: 1000}
      containers:
        - name: paperless
          image: ghcr.io/paperless-ngx/paperless-ngx:2.11
          env:
            - {name: TZ, value: America/Sao_Paulo}
          securityContext:
            allowPrivilegeEscalation: false
            capabilities: {drop: [ALL]}
          resources:
            requests: {memory: 512Mi, cpu: 100m}
            limits: {memory: 2Gi}
          livenessProbe:
            httpGet: {path: /, port: 8000}
          readinessProbe:
            httpGet: {path: /, port: 8000}

